{'name': {'value': 'Fountain9', 'matchLevel': 'none', 'matchedWords': []}, 'website': {'value': 'https://www.fountain9.com', 'matchLevel': 'none', 'matchedWords': []}, 'all_locations': {'value': 'Mumbai, MH, India; San Francisco, CA, USA', 'matchLevel': 'none', 'matchedWords': []}, 'long_description': {'value': 'Fountain9 is a predictive inventory planning solution. We help food brands and retailers reduce food wastage and improve product availability by predicting their future inventory needs. 

