{'name': {'value': 'Doomersion', 'matchLevel': 'none', 'matchedWords': []}, 'former_names': [{'value': 'Doomlingo', 'matchLevel': 'none', 'matchedWords': []}], 'website': {'value': 'https://doomersion.com/', 'matchLevel': 'none', 'matchedWords': []}, 'all_locations': {'value': 'Remote', 'matchLevel': 'none', 'matchedWords': []}, 'long_description': {'value': 'Doomersion (formerly Doomlingo) lets you learn languages by doomsrolling! Watch TikToks in your target language that are exactly matched to your level, and as you scroll, they get a little bit harder.

