{'name': {'value': 'Cumulus Labs', 'matchLevel': 'none', 'matchedWords': []}, 'former_names': [{'value': 'Cumulus', 'matchLevel': 'none', 'matchedWords': []}], 'website': {'value': 'https://cumuluslabs.io', 'matchLevel': 'none', 'matchedWords': []}, 'all_locations': {'value': '', 'matchLevel': 'none', 'matchedWords': []}, 'long_description': {'value': 'Cumulus Labs is a fast multimodal inference provider, purpose-built for AI teams who want faster performance, lower costs, and zero infrastructure work on fine-tuned & open source models.

