{'name': {'value': 'Jeevy Fabrication', 'matchLevel': 'none', 'matchedWords': []}, 'former_names': [{'value': 'Jeevy Data', 'matchLevel': 'none', 'matchedWords': []}, {'value': 'Jeevy Automation', 'matchLevel': 'none', 'matchedWords': []}], 'website': {'value': 'https://www.jeevyfabrication.com/', 'matchLevel': 'none', 'matchedWords': []}, 'all_locations': {'value': '', 'matchLevel': 'none', 'matchedWords': []}, 'long_description': {'value': 'Jeevy Fabrication is an AI-powered contractor that connects complex weld jobs to the best-fit shops—fast. We deliver top-tier QA and total transparency, all at better traditional outsourced pricing.

