{'name': {'value': 'Blaxel', 'matchLevel': 'none', 'matchedWords': []}, 'former_names': [{'value': 'Beamlit', 'matchLevel': 'none', 'matchedWords': []}], 'website': {'value': 'https://blaxel.ai', 'matchLevel': 'none', 'matchedWords': []}, 'all_locations': {'value': 'San Francisco, CA, USA', 'matchLevel': 'none', 'matchedWords': []}, 'long_description': {'value': 'Blaxel is the perpetual sandbox platform for AI agents that need to run code fast.

