{'name': {'value': 'Gigacatalyst', 'matchLevel': 'none', 'matchedWords': []}, 'former_names': [{'value': 'Giga Next Inc', 'matchLevel': 'none', 'matchedWords': []}, {'value': 'Giga Catalyst', 'matchLevel': 'none', 'matchedWords': []}], 'website': {'value': 'https://gigacatalyst.com/', 'matchLevel': 'none', 'matchedWords': []}, 'all_locations': {'value': 'San Francisco, CA, USA', 'matchLevel': 'none', 'matchedWords': []}, 'long_description': {'value': "We provide a AI customization layer that learns your APIs and embeds in your product, so your customers can build their own apps on your SaaS. Each customer can now adapt your product to match their workflows perfectly, and share it across their team with our in-built app store.

